import{_ as i,o as t,c as n,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Timeline & Scene Editing","description":"Master the script panel, timeline navigation, and scene controls.","frontmatter":{"title":"Timeline & Scene Editing","description":"Master the script panel, timeline navigation, and scene controls."},"headers":[],"relativePath":"user_guides/timeline-editing.md","filePath":"user_guides/timeline-editing.md"}'),o={name:"user_guides/timeline-editing.md"};function r(s,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="timeline-scene-editing" tabindex="-1">Timeline &amp; Scene Editing <a class="header-anchor" href="#timeline-scene-editing" aria-label="Permalink to &quot;Timeline &amp; Scene Editing&quot;">​</a></h1><p>The Unified Studio gives you granular control over every second of your production.</p><h2 id="the-script-panel" tabindex="-1">The Script Panel <a class="header-anchor" href="#the-script-panel" aria-label="Permalink to &quot;The Script Panel&quot;">​</a></h2><p>The left panel holds your parsed script. Each block represents a &quot;Scene&quot;.</p><h3 id="editing-text" tabindex="-1">Editing Text <a class="header-anchor" href="#editing-text" aria-label="Permalink to &quot;Editing Text&quot;">​</a></h3><p>Simply click on the text inside a scene block to edit it. Changes are saved automatically. Note that editing text <em>after</em> generating audio will require you to re-generate the audio track to match the new text.</p><h3 id="assigning-speakers" tabindex="-1">Assigning Speakers <a class="header-anchor" href="#assigning-speakers" aria-label="Permalink to &quot;Assigning Speakers&quot;">​</a></h3><p>Next to each line of dialogue, use the dropdown to assign a character from your Cast. If the line is an action/setting description, assign it to the &quot;Narrator&quot;.</p><h3 id="splitting-and-merging" tabindex="-1">Splitting and Merging <a class="header-anchor" href="#splitting-and-merging" aria-label="Permalink to &quot;Splitting and Merging&quot;">​</a></h3><ul><li><strong>Split:</strong> Hit <code>Enter</code> inside a scene to split it into two distinct scenes.</li><li><strong>Merge:</strong> Use the &quot;Merge Up&quot; icon on a scene block to combine it with the previous scene.</li></ul><h2 id="the-timeline-panel" tabindex="-1">The Timeline Panel <a class="header-anchor" href="#the-timeline-panel" aria-label="Permalink to &quot;The Timeline Panel&quot;">​</a></h2><p>The bottom timeline provides a horizontal view of your video sequence.</p><ul><li><strong>Playback:</strong> Use the playhead to scrub through your generated audio and visuals in sequence.</li><li><strong>Reordering:</strong> Drag and drop scenes in the timeline to change their order in the final video.</li></ul>',13)])])}const u=i(o,[["render",r]]);export{p as __pageData,u as default};
